{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "시정명령을 받은 사육자의 조치 결과를 서울시 홈페이지에서 공개할 수 있는지 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울특별시 동물보호 조례 제23조제2항에 따르면, 시장 또는 구청장은 동물의 보호 및 공중위생상의 위해방지를 위하여 필요하거나 시설기준 등에 맞지 않을 때에는 동물의 소유자등에 대하여 시정명령 등의 조치를 할 수 있고, 그 결과를 시의 홈페이지 또는 시보 등을 통해 공개할 수 있다. 따라서 시정명령을 받은 사육자의 조치 결과를 서울시 홈페이지에서 공개하는 것은 가능하다.",
          "b_ids": "동물보호:제23조제2항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
